def bubble(data):
    a = data[:]
    tukar = 0
    for i in range(len(a)):
        for j in range(len(a) - 1 - i):
            if a[j] > a[j + 1]:
                a[j], a[j + 1] = a[j + 1], a[j]
                tukar += 1
    return a, tukar

def insertion(data):
    a = data[:]
    for i in range(1, len(a)):
        kunci, j = a[i], i - 1
        while j >= 0 and a[j] > kunci:
            a[j + 1] = a[j]
            j -= 1
        a[j + 1] = kunci
    return a

