def kahn(g):
    masuk = {s: 0 for s in g}
    for s in g:
        for t in g[s]:
            masuk[t] += 1
    q = deque(s for s in g if masuk[s] == 0)
    urutan = []
    while q:
        s = q.popleft()
        urutan.append(s)
        for t in g[s]:
            masuk[t] -= 1
            if masuk[t] == 0:
                q.append(t)
    return urutan if len(urutan) == len(g) else 'ada siklus'

