from functools import lru_cache

@lru_cache(maxsize=None)
def cara_memo(n):
    if n <= 1:
        return 1
    return cara_memo(n - 1) + cara_memo(n - 2)

def cara_tabel(n):
    dp = [1] * (n + 1)
    for i in range(2, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]
    return dp

